mapper.select:
SELECT w.id, w.code, w.device_id, d.name AS device_name, w.type, w.status, w.assignee, w.description, w.create_time, w.finish_time FROM work_order w LEFT JOIN device d ON w.device_id = d.id
AND w.status = #{status}
AND w.type = #{type}
AND (w.code LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY w.id DESC
